function isNumberPart(part) {
  if (part === "" || (part.length > 1 && part[0] === "0")) return false;
  for (const c of part) if (c < "0" || c > "9") return false;
  return true;
}

function parseVersion(text) {
  const parts = text.split(".");
  if (parts.length !== 3 || parts.some(p => !isNumberPart(p))) throw new Error(`bad version ${text}`);
  return parts.map(Number);
}

function compareVersions(a, b) {
  const x = parseVersion(a), y = parseVersion(b);
  for (let i = 0; i < 3; i++) if (x[i] !== y[i]) return x[i] - y[i];
  return 0;
}

function upperBound(op, [major, minor, patch]) {
  if (op === "~") return `${major}.${minor + 1}.0`;
  if (major > 0) return `${major + 1}.0.0`;
  if (minor > 0) return `0.${minor + 1}.0`;
  return `0.0.${patch + 1}`;
}

function satisfies(version, range) {
  if (range === "*") { parseVersion(version); return true; }
  let op = "";
  if (range.startsWith(">=")) op = ">=";
  else if (range.startsWith("~") || range.startsWith("^")) op = range[0];
  const baseText = range.slice(op.length);
  let base;
  try { base = parseVersion(baseText); } catch { throw new Error(`bad range ${range}`); }
  const low = compareVersions(version, baseText);
  if (op === "") return low === 0;
  if (op === ">=") return low >= 0;
  return low >= 0 && compareVersions(version, upperBound(op, base)) < 0;
}

function maxSatisfying(versions, range) {
  const ok = versions.filter(v => satisfies(v, range));
  if (ok.length === 0) return null;
  return ok.reduce((best, v) => (compareVersions(v, best) > 0 ? v : best));
}

unitTests:
test("parsing and comparing", () => {
  checkEq(parseVersion("4.10.0"), [4, 10, 0]);
  checkThrows(() => parseVersion("1.2"));
  checkThrows(() => parseVersion("01.2.3"));
  checkThrows(() => parseVersion("1.2.3-beta"));
  check(compareVersions("1.10.0", "1.9.0") > 0, "1.10.0 is higher than 1.9.0");
  check(compareVersions("2.0.0", "10.0.0") < 0, "2 is lower than 10");
  checkEq(compareVersions("1.2.3", "1.2.3"), 0);
  checkEq(["1.10.0", "1.2.0", "0.9.9"].sort(compareVersions), ["0.9.9", "1.2.0", "1.10.0"]);
});

test("caret and tilde ranges", () => {
  checkEq(["1.2.3", "1.9.9", "2.0.0", "1.2.2"].map(v => satisfies(v, "^1.2.3")), [true, true, false, false]);
  checkEq(["1.2.3", "1.2.9", "1.3.0"].map(v => satisfies(v, "~1.2.3")), [true, true, false]);
  checkEq(["0.2.3", "0.2.9", "0.3.0"].map(v => satisfies(v, "^0.2.3")), [true, true, false]);
  checkEq(["0.0.3", "0.0.4"].map(v => satisfies(v, "^0.0.3")), [true, false]);
});

test("exact, at-least and any", () => {
  checkEq([satisfies("1.0.0", "1.0.0"), satisfies("1.0.1", "1.0.0")], [true, false]);
  checkEq([satisfies("3.0.0", ">=2.5.0"), satisfies("2.4.9", ">=2.5.0")], [true, false]);
  checkEq(satisfies("9.9.9", "*"), true);
  checkThrows(() => satisfies("1.0.0", "<2.0.0"));
  try { satisfies("1.0.0", "^1.x"); } catch (e) { checkEq(e.message, "bad range ^1.x"); }
});

test("picking the highest match", () => {
  const published = ["1.0.0", "1.4.2", "1.10.1", "2.0.0", "2.1.0"];
  checkEq(maxSatisfying(published, "^1.2.0"), "1.10.1");
  checkEq(maxSatisfying(published, "~1.4.0"), "1.4.2");
  checkEq(maxSatisfying(published, "^3.0.0"), null);
  checkEq(maxSatisfying(published, "*"), "2.1.0");
});

